import { MutableRefObject, useCallback, useEffect, useMemo, useState } from 'react';

import OpenFin from '@openfin/core';

import { BookmarkFolder, getBookmarkNodeTitle } from '@common/utils/bookmarks';
import { getBrowserWindowWithoutView } from '@common/utils/get-browser-window';
import { showSuccess } from '@common/utils/indicators/showIndicator';
import { BookmarkButtonPayload } from '@common/utils/popup-window';

import { useTranslation } from '@common/api/i18next';
import { BookmarkNode } from '@common/api/pages/shapes';

import { searchBookmark } from '@enterprise/components/ControlBar/SearchMenu/utils';

type UpdatableFields = {
    title: string;
    folderId: string;
    favIcon: string;
};

/**
 * This hook is used to manage the form state of the bookmark dialog.
 * It is used to create, update, and delete bookmarks.
 * It is used in the bookmark dialog.
 *
 * @param {BookmarkButtonPayload} bookmarkPayload - The payload of the bookmark button.
 * @param {Function} onResponse - The callback function to call when the dialog is closed.
 * @param {BookmarkFolder} defaultBookmarkFolder - The default bookmark folder.
 * @param {BookmarkFolder[]} bookmarkFolders - The list of bookmark folders.
 * @param {MutableRefObject<HTMLInputElement>} [titleInputRef] - The reference to the title input element.
 *
 * @returns {Object} The state and handlers for the bookmark dialog form.
 */
export const useBookmarkDialogForm = (
    bookmarkPayload: BookmarkButtonPayload,
    onResponse: (data?: any) => void,
    defaultBookmarkFolder: BookmarkFolder,
    bookmarkFolders: BookmarkFolder[],
    titleInputRef?: MutableRefObject<HTMLInputElement>
) => {
    const { t } = useTranslation();
    const [isNewBookmark, setIsNewBookmark] = useState<boolean>(false);
    const [existingBookmark, setExistingBookmark] = useState<BookmarkNode>();
    const [fields, setFields] = useState<UpdatableFields>({
        title: '',
        folderId: '',
        favIcon: ''
    });
    const [initialFolder, setInitialFolder] = useState<string>('');
    const [browserIdentity, setBrowserIdentity] = useState<OpenFin.Identity>();

    useEffect(() => {
        (async () => {
            if (!bookmarkPayload?.selectedViewIdentity) {
                return;
            }
            const view = fin.View.wrapSync(bookmarkPayload.selectedViewIdentity);

            const viewInfo = await view.getInfo();
            const viewTitle = viewInfo.title;
            const viewFavIcon = viewInfo.favicons[0];
            const viewUrl = viewInfo.url;
            const viewBrowserIdentity = (await view.getCurrentWindow()).identity;

            let bookmark = await searchBookmark(viewUrl, viewBrowserIdentity);

            if (!bookmark) {
                setIsNewBookmark(true);
                const browserWindow = await getBrowserWindowWithoutView(viewBrowserIdentity);
                // eslint-disable-next-line no-underscore-dangle
                bookmark = await browserWindow._bookmarks._createBookmarkNode({
                    url: viewUrl,
                    title: viewTitle,
                    favIcon: viewFavIcon,
                    parentId: defaultBookmarkFolder?.id
                });
                onResponse({ type: 'bookmark-created' });
            }

            setBrowserIdentity(viewBrowserIdentity);
            setExistingBookmark(bookmark);
            setFields({
                title: bookmark.title,
                folderId: bookmark.parentId,
                favIcon: viewFavIcon
            });
            setInitialFolder(bookmark.parentId);

            titleInputRef?.current.select();
        })();
    }, [bookmarkPayload, defaultBookmarkFolder?.id, onResponse, titleInputRef]);

    const resetForm = useCallback(() => {
        setFields({
            title: '',
            folderId: '',
            favIcon: ''
        });
        setExistingBookmark(undefined);
        setIsNewBookmark(false);
    }, []);

    const showSuccessIndicator = useCallback(() => {
        const bookmarkFolder = bookmarkFolders?.find((folder) => folder.id === fields.folderId);
        if (bookmarkFolder) {
            if (isNewBookmark || initialFolder !== fields.folderId) {
                showSuccess({
                    message: t(isNewBookmark ? 'bookmarks.bookmarkAddedTitle' : 'bookmarks.bookmarkEditedTitle'),
                    parentBrowserName: browserIdentity.name,
                    secondaryMessage: t('bookmarks.bookmarkAddedToFolder', {
                        folderName: getBookmarkNodeTitle(bookmarkFolder?.title)
                    }),
                    icon: 'BookmarkFilled'
                });
            }
        }
    }, [bookmarkFolders, browserIdentity, fields.folderId, initialFolder, isNewBookmark, t]);

    const saveBookmark = useCallback(async () => {
        if (!existingBookmark) {
            return;
        }
        const browserWindow = await getBrowserWindowWithoutView(browserIdentity);
        // eslint-disable-next-line no-underscore-dangle
        await browserWindow._bookmarks._updateBookmarkNode({
            id: existingBookmark.id,
            changes: {
                title: fields.title,
                // We DO NOT update the favicon here, as it is not guaranteed to be correct here
                // favIcon: fields.favIcon,
                parentId: fields.folderId
            }
        });

        showSuccessIndicator();
        onResponse && onResponse({ type: 'bookmark-updated' });
        resetForm();
    }, [existingBookmark?.id, fields.title, fields.favIcon, fields.folderId, onResponse, resetForm, initialFolder]);

    const removeBookmark = useCallback(async () => {
        const browserWindow = await getBrowserWindowWithoutView();
        if (existingBookmark) {
            // eslint-disable-next-line no-underscore-dangle
            await browserWindow._bookmarks._deleteBookmarkNode(existingBookmark.id);
            onResponse && onResponse({ type: 'bookmark-removed' });
        }
        resetForm();
    }, [existingBookmark, onResponse, resetForm]);

    return useMemo(
        () => ({
            title: fields.title,
            setTitle: (title: string) => {
                setFields((prevFields) => ({
                    ...prevFields,
                    title
                }));
            },
            folderId: fields.folderId,
            setFolderId: (folderId: string) => {
                setFields((prevFields) => ({
                    ...prevFields,
                    folderId
                }));
            },
            saveBookmark,
            removeBookmark,
            resetForm,
            isNewBookmark
        }),
        [fields.title, fields.folderId, saveBookmark, removeBookmark, resetForm, isNewBookmark]
    );
};
