import { IconType } from '@openfin/ui-library';

import { getBrowserBaseUrl, getEnterpriseBaseUrl } from '@common/utils/browser-base-url';
import { isEnterpriseBrowser } from '@common/utils/enterpriseBrowser';
import { finUUID } from '@common/utils/env';
import { PositioningType } from '@common/utils/positioning';
import Route from '@common/utils/route';
import { getOFWindow, serializeWindowBounds, WindowName } from '@common/utils/window';

import { t } from '@common/api/i18next';
import { BrowserChannelAction, getChannelClient } from '@common/api/protocol/browser';

import { IndicatorType } from '@common/components/Indicator/Indicator.constants';

import makeShowIndicator from './helper';
import { getSuppressWorkspaceSaved, getSuppressWorkspaceSwitched } from './workspace-indicators';

export type IndicatorIcon = Extract<
    IconType,
    'LockClosedIcon' | 'LockOpen1Icon' | 'PageIcon' | 'BlockedIcon' | 'SupertabIcon' | 'BookmarkFilled'
>;

const namespace = 'browser';
const makeIndicator = makeShowIndicator();

export interface ShowIndicatorPayload {
    type: IndicatorType;
    message: string;
    parentBrowserName?: string;
    secondaryMessage?: string;
    icon?: IndicatorIcon;
    isEnterprise?: boolean;
    positioning?: PositioningType;
}

export interface ShowErrorPayload {
    message: string;
    parentBrowserName?: string;
    icon?: IndicatorIcon;
    isEnterprise?: boolean;
    positioning?: PositioningType;
}

export interface ShowSuccessPayload {
    message: string;
    parentBrowserName?: string;
    secondaryMessage?: string;
    icon?: IndicatorIcon;
    isEnterprise?: boolean;
    positioning?: PositioningType;
}

export interface ShowInfoPayload {
    message: string;
    parentBrowserName?: string;
    icon?: IndicatorIcon;
    isEnterprise?: boolean;
}

/**
 * Creates a window containing a visual indicator directly
 * This function handles the actual indicator creation
 */
async function showIndicatorDirect(payload: ShowIndicatorPayload): Promise<void> {
    const { type, message, parentBrowserName, secondaryMessage, icon, isEnterprise, positioning } = payload;
    const params = new URLSearchParams();
    params.append('type', type);
    params.append('message', message);
    params.append('parentName', parentBrowserName || '');
    params.append('secondaryMessage', secondaryMessage || '');
    params.append('icon', icon || '');
    params.append('isEnterprise', `${isEnterprise}` || '');
    if (positioning === PositioningType.RelativeToMonitor) {
        params.append('positioning', PositioningType.RelativeToMonitor);
    }

    if (parentBrowserName) {
        const browserIdentity = parentBrowserName ? { uuid: finUUID, name: parentBrowserName } : undefined;
        const browserWindow = getOFWindow(browserIdentity);
        const browserBounds = serializeWindowBounds(await browserWindow.getBounds());
        params.append('parentBounds', browserBounds);
    }

    const baseUrl = isEnterprise ? await getEnterpriseBaseUrl() : await getBrowserBaseUrl();
    const url = `${baseUrl + Route.BrowserIndicator}#${params.toString()}`;
    return makeIndicator(namespace + parentBrowserName, url, message, type, secondaryMessage);
}

/**
 * Creates a window containing a visual indicator contained in a Browser Window
 * This function decides whether to call browser function or direct function
 */
export async function showIndicator(payload: ShowIndicatorPayload): Promise<void> {
    const { parentBrowserName } = payload;
    const isBrowserWindow = parentBrowserName && parentBrowserName.includes(WindowName.BrowserWindow);
    if (isBrowserWindow && fin.me.name !== parentBrowserName) {
        // ferry all browser indicator calls to the parentBrowserWindow it relates to
        const channel = await getChannelClient({ uuid: fin.me.uuid, name: parentBrowserName });
        return channel.dispatch(BrowserChannelAction.ShowBrowserIndicator, payload);
    }
    return showIndicatorDirect(payload);
}

/**
 * Creates a window containing an error indicator
 */
export async function showError(payload: ShowErrorPayload): Promise<void> {
    const isEnterprise =
        payload.isEnterprise ??
        (await isEnterpriseBrowser(
            payload.parentBrowserName ? { uuid: finUUID, name: payload.parentBrowserName } : undefined
        ));
    const finalPayload: ShowIndicatorPayload = {
        type: 'error',
        message: payload.message,
        parentBrowserName: payload.parentBrowserName,
        icon: payload.icon,
        isEnterprise,
        positioning: payload.positioning
    };
    return showIndicator(finalPayload);
}

