/**
 * Creates a window centered on monitor containing a success indicator for switching workspaces.
 * No-ops when `suppressWorkspaceSwitched` has been set via `BrowserInitConfig.indicators`.
 */
export function showSwitchWorkspaceSuccess(): Promise<void> {
    if (getSuppressWorkspaceSwitched()) return Promise.resolve();
    const payload: ShowIndicatorPayload = {
        type: 'success',
        message: t('successIndicator.workspaceSwitched'),
        positioning: PositioningType.RelativeToMonitor
    };
    return showIndicator(payload);
}

/**
 * Creates a success indicator for workspace save and save-as operations.
 * No-ops when `suppressWorkspaceSaved` has been set via `BrowserInitConfig.indicators`.
 * Rename operations are intentionally unaffected — use `showSuccess` directly for those.
 */
export const showWorkspaceSavedSuccess = (payload: ShowSuccessPayload): Promise<void> => {
    if (getSuppressWorkspaceSaved()) return Promise.resolve();
    return showSuccess(payload);
};
