import { MutableRefObject, useEffect, useState } from 'react';

import { OpenFin } from '@openfin/core';

import { BookmarkFolder, getBookmarkFoldersList } from '@common/utils/bookmarks';
import { getBrowserWindowWithoutView } from '@common/utils/get-browser-window';

import { BrowserChannelAction } from '@common/api/protocol/browser';

/*
 * This hook is used to get all bookmark folders.
 */
export const useBookmarkFolders = (channel?: MutableRefObject<OpenFin.ChannelProvider>): Array<BookmarkFolder> => {
    const [folders, setFolders] = useState<Array<BookmarkFolder>>([]);

    useEffect(() => {
        const refreshBookmarkFolders = () => {
            getBrowserWindowWithoutView().then(async (browserWin) =>
                // eslint-disable-next-line no-underscore-dangle
                browserWin._bookmarks
                    ._getBookmarkNode()
                    .then((bookmarkRootNode) => setFolders(getBookmarkFoldersList(bookmarkRootNode)))
            );
        };

        refreshBookmarkFolders();

        (async () => {
            if (channel?.current) {
                channel.current.register(BrowserChannelAction.RefreshBookmarksInternal, refreshBookmarkFolders);
            }
        })();
    }, [channel?.current]);

    return folders;
};
